const texte = item.json.histoire_finale || "";

// Compte les mots : trim() + split sur espaces/retours à la ligne
const wordCount = texte.trim() ? texte.trim().split(/\s+/).length : 0;

// Ajoute le résultat au JSON
item.json.histoire_finale_word_count = wordCount;

return items;

console.log('🚀 Début du traitement de l\'extraction...');

try {
  // ✅ Étape 1 : Sécuriser l'accès à items
  if (!items || items.length === 0) {
    return [{
      json: {
        error: 'Aucun item en input',
        received: items
      }
    }];
  }

  console.log('✅ Items reçus, nombre:', items.length);

  // ✅ Étape 2 : Accéder à l'objet principal
  const responseData = items[0].json;
  console.log('✅ Données de réponse trouvées');

  // ✅ Étape 3 : Trouver le message (output[1] car output[0] est reasoning)
  if (!responseData.output || !Array.isArray(responseData.output)) {
    return [{
      json: {
        error: 'Structure output invalide',
        received: responseData.output
      }
    }];
  }

  // Chercher l'élément avec type "message"
  const messageOutput = responseData.output.find(item => item.type === 'message');

  if (!messageOutput || !messageOutput.content) {
    return [{
      json: {
        error: 'Élément message non trouvé',
        outputStructure: responseData.output.map(o => ({ id: o.id, type: o.type }))
      }
    }];
  }

  console.log('✅ Message trouvé');

  // ✅ Étape 4 : Récupérer le contenu texte
  const messageContent = messageOutput.content[0];
  if (!messageContent || !messageContent.text) {
    return [{
      json: {
        error: 'Contenu texte non trouvé',
        contentStructure: messageOutput.content
      }
    }];
  }

  console.log('✅ Contenu texte récupéré');

  // ✅ Étape 5 : Parser le JSON imbriqué
  let parsedJson;
  try {
    parsedJson = JSON.parse(messageContent.text);
    console.log('✅ JSON parsé avec succès');
  } catch (parseError) {
    return [{
      json: {
        error: 'Erreur lors du parsing JSON',
        details: parseError.message,
        rawText: messageContent.text.substring(0, 200)
      }
    }];
  }

  // ✅ Étape 6 : Extraire et structurer
  const extractedData = {
    summary: parsedJson.output.summary,
    story_analysis: {
      style: parsedJson.output.story_analysis.style,
      keywords: parsedJson.output.story_analysis.keywords,
      structure: parsedJson.output.story_analysis.structure,
      main_characters: parsedJson.output.story_analysis.main_characters,
      secondary_characters: parsedJson.output.story_analysis.secondary_characters,
      themes: parsedJson.output.story_analysis.themes
    },
    tokens: {
      input_tokens: parsedJson.input_tokens,
      output_tokens: parsedJson.output_tokens,
      model: parsedJson.model_llm
    }
  };

  console.log('✅ Données structurées avec succès');
