  console.log('🎭 Thèmes:', extractedData.story_analysis.themes.length);

  // ✅ Étape 7 : Retour
  return [{
    json: extractedData
  }];

} catch (err) {
  console.error('❌ ERREUR FATALE:', err.message);
  return [{
