  "tokens_contexte_autour_histoire1",
  "tokens_creation_image",
];

// 3. Fonction pour trouver le prix
function findPrice(modelName) {
  if (!modelName) return null;
  if (pricing[modelName]) return pricing[modelName];

  const keys = Object.keys(pricing).sort((a, b) => b.length - a.length);
  for (const key of keys) {
    if (modelName.includes(key)) {
      return pricing[key];
    }
  }
  return null;
}

// 4. Accéder au JSON d'entrée
const inputData = $input.first().json;

// 5. Fonction pour calculer le coût pour UN nœud
function computeCostForNodePrefix(prefix) {
  // Construire les clés attendues
  const modelKey = `${prefix}_model_llm`;
  const inputKey = `${prefix}_input_tokens`;
  const outputKey = `${prefix}_output_tokens`;

  // Vérifier si les données existent
  if (!inputData[modelKey]) {
    return {
      nodeName: prefix,
      status: "no_data_found",
      cost_total_usd: 0,
      input_tokens: 0,
      output_tokens: 0,
    };
  }

  const model = inputData[modelKey];
  const inputTokens = Number(inputData[inputKey] || 0);
  const outputTokens = Number(inputData[outputKey] || 0);

  const modelPrice = findPrice(model);

  if (!modelPrice) {
    return {
      nodeName: prefix,
      model_llm: model,
      status: "price_not_found",
      input_tokens: inputTokens,
      output_tokens: outputTokens,
      cost_total_usd: 0,
    };
  }

  const costInput = (inputTokens / 1000000) * modelPrice.input;
  const costOutput = (outputTokens / 1000000) * modelPrice.output;
  const costTotal = costInput + costOutput;

  return {
    nodeName: prefix,
    model_llm: model,
    status: "success",
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    cost_input_usd: Number(costInput.toFixed(6)),
    cost_output_usd: Number(costOutput.toFixed(6)),
    cost_total_usd: Number(costTotal.toFixed(6)),
  };
}

// 6. Exécution
let totalInputTokens = 0;
let totalOutputTokens = 0;
let totalCostFromTokens = 0;

const details = tokenNodePrefixes.map((prefix) => {
  const res = computeCostForNodePrefix(prefix);
  totalInputTokens += res.input_tokens;
  totalOutputTokens += res.output_tokens;
  totalCostFromTokens += res.cost_total_usd;
  return res;
});

