    cost_from_token_nodes: Number(totalCostFromTokens.toFixed(6)),
    cost_from_titles: Number(costTitresUsd.toFixed(6)),
    total_cost_usd: Number(totalCostUsd.toFixed(6)),
  },

  details_par_noeud: details,
};

return [{ json: result }];

// On récupère la donnée d'entrée
let response = $input.item.json.output || $input.item.json;

if (typeof response === 'string') {
  // 1. Nettoyage des balises Markdown (```json, ```, etc.)
  // On utilise une expression régulière pour enlever tout ce qui ressemble à des blocs de code
  let cleanedResponse = response
    .replace(/```json/g, '') // Enlève le début du bloc
    .replace(/```/g, '')     // Enlève la fin du bloc
    .trim();                 // Enlève les espaces/retours à la ligne inutiles au début et à la fin

  try {
    // 2. Tentative de parsing du texte nettoyé
    const parsed = JSON.parse(cleanedResponse);
    return [{ json: parsed }];
  } catch (error) {
    // En cas d'échec, on renvoie l'erreur pour pouvoir débugger
    return [{
      json: {
        error: 'Erreur de parsing JSON',
        message: error.message,
        tried_to_parse: cleanedResponse,
        original_raw: response
      }
    }];
  }
}

// Si ce n'est pas un string, on le renvoie tel quel
return [{ json: response }];

const response = items[0].json.output || items[0].json;

// Parse si c'est une string
let parsed = typeof response === 'string' 
  ? JSON.parse(response) 
  : response;

// Correction : On s'assure que 'json' reçoit un objet
// Si 'parsed' est déjà un objet, on le passe. 
// Sinon, on le place dans une propriété (ex: "data")
return [{
  json: (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) 
    ? parsed 
    : { data: parsed }
}];

