// n8n Code Node - JavaScript

// 1. Table de prix (J'ai ajouté une logique de recherche "floue" plus bas pour gérer les dates)
const pricing = {
  "gpt-5": { input: 0.625, output: 5.0 },
  "gpt-5-mini": { input: 0.125, output: 1.0 }, // Le code va matcher "gpt-5-mini-2025..." avec ça
  "gpt-5-nano": { input: 0.025, output: 0.2 },
  "gpt-4.1": { input: 1.0, output: 4.0 },
  "gpt-4.1-mini": { input: 0.2, output: 0.8 },
  "gpt-4.1-nano": { input: 0.05, output: 0.2 },
  "gpt-4o": { input: 1.25, output: 5.0 },
  "gpt-4o-mini": { input: 0.075, output: 0.3 },
  "o3-pro": { input: 10.0, output: 40.0 },
  "o3": { input: 1.0, output: 4.0 },
  "o3-deep-research": { input: 5.0, output: 20.0 },
  "o4-mini": { input: 0.55, output: 2.2 },
  "o1": { input: 7.5, output: 30.0 },
  "o1-pro": { input: 75.0, output: 300.0 },
  "o1-mini": { input: 0.55, output: 2.2 },
  "computer-use-preview": { input: 1.5, output: 6.0 },
  "gemini-3-pro": { input: 2.00, output: 12.00 },
  "gemini-3-flash": { input: 0.50, output: 3.00 },
  "gemini-2.5-pro": { input: 1.25, output: 10.00 },
  "gemini-2.5-flash": { input: 0.30, output: 2.50 },
};

// 2. Liste EXACTE des noms de tes nœuds (Doit matcher l'interface n8n)
const tokenNodes = [
  "tokens_creation_histoire",
  "tokens_verif_creation_histoire",
  "tokens_contexte_autour_histoire2",
  "tokens_creation_image1",
  "tokens_allonge_histoire",
  "tokens_verif_creation_histoire1",
  "tokens_contexte_autour_histoire1",
  "tokens_creation_image",
];

// 3. Fonction pour trouver le prix même si le nom a une date (ex: gpt-5-mini-2025-08-07)
function findPrice(modelName) {
  if (!modelName) return null;

  // Essai 1 : Match exact
  if (pricing[modelName]) return pricing[modelName];

  // Essai 2 : Match partiel (ex: "gpt-5-mini" dans "gpt-5-mini-2025...")
  // On trie les clés par longueur décroissante pour matcher le plus spécifique en premier
  const keys = Object.keys(pricing).sort((a, b) => b.length - a.length);
  for (const key of keys) {
    if (modelName.includes(key)) {
      return pricing[key];
    }
  }
  return null;
}

// 4. Fonction principale de calcul
function computeCostForNode(nodeName) {
  let nodeData;

  // --- CORRECTION MAJEURE ICI : Utilisation de $('NodeName') ---
  try {
    // On essaie de récupérer les données du nœud spécifique
    // .first().json prend le 1er item du tableau [{...}]
    nodeData = $(nodeName).first().json; 
  } catch (error) {
    // Si le nœud n'a pas encore couru ou n'existe pas
    return {
      nodeName,
      status: "node_not_found_or_not_executed",
      cost_total_usd: 0,
      input_tokens: 0,
      output_tokens: 0
    };
  }

  // Sécurisation si nodeData est vide
  if (!nodeData) {
    return { nodeName, status: "empty_data", cost_total_usd: 0, input_tokens: 0, output_tokens: 0 };
  }

  const model = nodeData.model_llm;
  const inputTokens = Number(nodeData.input_tokens || 0);
  const outputTokens = Number(nodeData.output_tokens || 0);

  // Recherche du prix intelligent
  const modelPrice = findPrice(model);

  if (!modelPrice) {
    return {
      nodeName,
      model_llm: model,
      status: "price_not_found",
      input_tokens: inputTokens,
      output_tokens: outputTokens,
      cost_total_usd: 0
    };
  }

  const costInput = (inputTokens / 1000000) * modelPrice.input;
  const costOutput = (outputTokens / 1000000) * modelPrice.output;
  const costTotal = costInput + costOutput;

  return {
    nodeName,
    model_llm: model, // Affiche le modèle réel reçu (ex: avec la date)
    status: "success",
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    cost_input_usd: Number(costInput.toFixed(6)),
    cost_output_usd: Number(costOutput.toFixed(6)),
    cost_total_usd: Number(costTotal.toFixed(6)),
  };
}

// 5. Exécution
let totalInputTokens = 0;
let totalOutputTokens = 0;
let totalCostUsd = 0;

const details = tokenNodes.map((name) => {
  const res = computeCostForNode(name);
  totalInputTokens += res.input_tokens;
  totalOutputTokens += res.output_tokens;
  totalCostUsd += res.cost_total_usd;
  return res;
});

const result = {
  timestamp: new Date().toISOString(),
  total_input_tokens: totalInputTokens,
  total_output_tokens: totalOutputTokens,
  total_cost_usd: Number(totalCostUsd.toFixed(6)),
  details_par_noeud: details,
};

return [ { json: result } ];

